insert into audio_clips (id, text, voice, channel) values ('435280fa25813318', 'お疲れさまです。前回ご説明した役員体制案について、変更がありましたのでご報告します。', 'manager_m', 'phone') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
insert into audio_clips (id, text, voice, channel) values ('bd564e8efb2cdb8a', 'お願いします。前回は社外から監査役を一名招聘し、取締役は八名を維持するという内容でしたね。', 'staff_junior_m', 'phone') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
insert into audio_clips (id, text, voice, channel) values ('eb9927bd090e87e2', 'はい、そうでした。昨日の経営会議で、取締役を八名から五名に減らす案が出たのですが、株主からの反発が予想されるとのことで、結局六名に落ち着きました。', 'manager_m', 'phone') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
insert into audio_clips (id, text, voice, channel) values ('7ae6f7abb68a30f6', '監査役のほうは、社外招聘のままですか。', 'staff_junior_m', 'phone') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
insert into audio_clips (id, text, voice, channel) values ('1e2b07f55179fe8b', 'いえ、そちらも変わりまして、社外から新たに迎えるのではなく、現在の顧問弁護士に監査役を兼任していただくことになりました。', 'manager_m', 'phone') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
insert into audio_clips (id, text, voice, channel) values ('cdeeedc7f89211d7', 'なるほど、人件費を抑える狙いですね。株主総会での承認はこれからですか。', 'staff_junior_m', 'phone') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
insert into audio_clips (id, text, voice, channel) values ('267d733f7763bdf4', 'はい、来月の総会にかけることになります。', 'manager_m', 'phone') on conflict (id) do update set text = excluded.text, voice = excluded.voice, channel = excluded.channel;
