insert into items (id, bundle_id, item_type, level, seed_cell_id, setting, relation, function, channel, scene_id, speaker_role, listener_role, topic, stem, correct_index, explanation_ja, explanation_en, vocab_notes, documents, dialogue, narration_clip_id, model_p_correct) values ('dd945a7ce3', 'sougou_choukai_J1_003', 'sougou_choukai', 'J1', 'conference_call+junior_to_senior+what_changed@J1', 'conference_call', 'junior_to_senior', 'what_changed', 'phone', 'scene_phone_desk', null, null, '役員体制案の変更点', '前回の役員体制案から、何が変わりましたか。', 0, '前回案は監査役を社外から一名招聘し取締役は八名を維持する内容だった。最終的には、取締役は五名案が一度検討されたものの株主の反発を懸念して六名に落ち着き、監査役は社外から新たに迎えるのではなく現職の顧問弁護士が兼任する形に変わった。五名案は途中で修正されており、兼任案は後輩が報告した内容であって先輩が提案したものではない。弁護士という語を使った選択肢も、実際には新規招聘ではなく既存顧問の兼任であり、事実と異なる。', 'The final plan settles on six directors (not five, which was floated and revised) and has the existing legal advisor take on the auditor role rather than hiring a new outside auditor; the proposal came from the junior''s report, not the senior''s suggestion.', '[{"term": "監査役", "reading": "かんさやく", "meaning": "company auditor (board-level oversight role)"}, {"term": "取締役", "reading": "とりしまりやく", "meaning": "director (board member)"}, {"term": "兼任", "reading": "けんにん", "meaning": "to hold a post concurrently"}, {"term": "招聘", "reading": "しょうへい", "meaning": "to invite/recruit (a person to a position)"}]', '[]', '[{"speaker_role": "後輩", "text": "お疲れさまです。前回ご説明した役員体制案について、変更がありましたのでご報告します。", "clip_id": "435280fa25813318"}, {"speaker_role": "先輩", "text": "お願いします。前回は社外から監査役を一名招聘し、取締役は八名を維持するという内容でしたね。", "clip_id": "bd564e8efb2cdb8a"}, {"speaker_role": "後輩", "text": "はい、そうでした。昨日の経営会議で、取締役を八名から五名に減らす案が出たのですが、株主からの反発が予想されるとのことで、結局六名に落ち着きました。", "clip_id": "eb9927bd090e87e2"}, {"speaker_role": "先輩", "text": "監査役のほうは、社外招聘のままですか。", "clip_id": "7ae6f7abb68a30f6"}, {"speaker_role": "後輩", "text": "いえ、そちらも変わりまして、社外から新たに迎えるのではなく、現在の顧問弁護士に監査役を兼任していただくことになりました。", "clip_id": "1e2b07f55179fe8b"}, {"speaker_role": "先輩", "text": "なるほど、人件費を抑える狙いですね。株主総会での承認はこれからですか。", "clip_id": "cdeeedc7f89211d7"}, {"speaker_role": "後輩", "text": "はい、来月の総会にかけることになります。", "clip_id": "267d733f7763bdf4"}]', '9327c4850de72c57', 1.0) on conflict (id) do update set bundle_id = excluded.bundle_id, item_type = excluded.item_type, level = excluded.level, seed_cell_id = excluded.seed_cell_id, setting = excluded.setting, relation = excluded.relation, function = excluded.function, channel = excluded.channel, scene_id = excluded.scene_id, speaker_role = excluded.speaker_role, listener_role = excluded.listener_role, topic = excluded.topic, stem = excluded.stem, correct_index = excluded.correct_index, explanation_ja = excluded.explanation_ja, explanation_en = excluded.explanation_en, vocab_notes = excluded.vocab_notes, documents = excluded.documents, dialogue = excluded.dialogue, narration_clip_id = excluded.narration_clip_id, model_p_correct = excluded.model_p_correct;
insert into item_options (item_id, position, text, role, why, clip_id) values ('dd945a7ce3', 0, '取締役は六名に減り、監査役は新たに迎えず顧問弁護士が兼任することになった。', 'correct', '後輩が経営会議の結果として報告した最終案で、取締役は六名、監査役は社外招聘をやめて現職の顧問弁護士が兼任すると述べている。', 'b360b9e9cfaf82e5') on conflict (item_id, position) do update set text = excluded.text, role = excluded.role, why = excluded.why, clip_id = excluded.clip_id;
